function openFilterSheet(){const bs=brands(),scrollY=window.scrollY;openSheet(`<div class="v10-filter-sheet"><div><small>MARCAS</small><h2>Encuentra tu marca</h2><p>Elige una marca sin perder tu lugar.</p></div><label class="v10-brand-search">${icon('search')}<input id="brandSearch" autocomplete="off" placeholder="Buscar marca"></label><div class="v10-brand-options"><button data-brand-option="" class="${!state.brand?'active':''}">Todas las marcas</button>${bs.map(b=>`<button data-brand-option="${escapeHTML(b)}" class="${norm(state.brand)===norm(b)?'active':''}">${escapeHTML(b)}</button>`).join('')}</div></div>`,sheet=>{$$('[data-brand-option]',sheet).forEach(b=>b.onclick=()=>{const value=b.dataset.brandOption||'';closeSheet(true);applyBrandFilter(value);requestAnimationFrame(()=>window.scrollTo(0,scrollY))});$('#brandSearch',sheet)?.addEventListener('input',e=>{const q=norm(e.target.value);$$('[data-brand-option]',sheet).forEach((b,i)=>{if(i===0)return;b.hidden=!!q&&!norm(b.textContent).includes(q)})})})}
