function openSheet(html,onMount){closeSheet(true);const host=$('#sheetHost');host.innerHTML=`<div class="v10-backdrop"></div><section class="v10-sheet"><div class="v10-grab"></div><button class="v10-sheet-close">×</button><div class="v10-sheet-scroll">${html}</div></section>`;state.sheetOpen=true;requestAnimationFrame(()=>{$('.v10-backdrop',host).classList.add('show');$('.v10-sheet',host).classList.add('show')});$('.v10-backdrop',host).onclick=()=>closeSheet();$('.v10-sheet-close',host).onclick=()=>closeSheet();onMount?.($('.v10-sheet',host))}
