function setupCarousel(){carouselToken++;const token=carouselToken,strip=$('#featuredStrip');if(!strip)return;const cards=[...strip.children];if(cards.length<2)return;const frag=document.createDocumentFragment();cards.forEach(c=>{const clone=c.cloneNode(true);clone.dataset.carouselClone='1';frag.append(clone)});strip.append(frag);let gesture=null,last=performance.now();const width=()=>{const first=strip.querySelector('.v10-product:not([data-carousel-clone])'),clone=strip.querySelector('[data-carousel-clone]');return first&&clone?clone.offsetLeft-first.offsetLeft:0};strip.addEventListener('pointerdown',e=>{if(!e.isPrimary)return;gesture={id:e.pointerId,x:e.clientX,y:e.clientY,mode:''}},{passive:true});strip.addEventListener('pointermove',e=>{if(!gesture||e.pointerId!==gesture.id||gesture.mode)return;const dx=e.clientX-gesture.x,dy=e.clientY-gesture.y;if(Math.max(Math.abs(dx),Math.abs(dy))<7)return;gesture.mode=Math.abs(dx)>Math.abs(dy)*1.15?'horizontal':'vertical'},{passive:true});const end=e=>{if(!gesture||e.pointerId!==gesture.id)return;gesture=null;last=performance.now()};strip.addEventListener('pointerup',end,{passive:true});strip.addEventListener('pointercancel',end,{passive:true});const tick=now=>{if(token!==carouselToken||!strip.isConnected)return;const dt=Math.min(40,Math.max(0,now-last));last=now;if(document.visibilityState==='visible'&&gesture?.mode!=='horizontal'){strip.scrollLeft+=dt*.022;const w=width();if(w&&strip.scrollLeft>=w)strip.scrollLeft-=w}requestAnimationFrame(tick)};requestAnimationFrame(tick)}
function updateNavigation(){const set=(id,n)=>{const el=$(id);if(!el)return;el.textContent=n>99?'99+':String(n);el.hidden=n<1};set('#favBadge',state.favorites.size);set('#orderBadge',state.history.length);set('#cartBadge',cartCount())}
function showView(name,{push=true,focusSearch=false}={}){const same=state.view===name;state.view=name;$$('[data-panel]').forEach(p=>p.classList.toggle('active',p.dataset.panel===name));$$('.v10-nav [data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===name));if(!same)window.scrollTo(0,0);if(name==='home'&&!rendered.home)renderHome();if(name==='catalog'&&!rendered.catalog)renderCatalog();if(name==='favorites')renderFavorites();if(name==='orders'){renderOrders();if(state.history.length)setTimeout(refreshOrders,0)}if(name==='cart')renderCart();if(push&&history.state?.v10View!==name)history.pushState({v10View:name},'',name==='home'?location.pathname:`${location.pathname}#${name}`);if(focusSearch&&name==='catalog')setTimeout(()=>$('#catalogSearch')?.focus({preventScroll:true}),0);updateNavigation()}
function bindGlobal(){document.addEventListener('click',e=>{const v=e.target.closest?.('[data-view]');if(v){e.preventDefault();showView(v.dataset.view,{focusSearch:v.hasAttribute('data-focus-search')});return}const j=e.target.closest?.('[data-category-jump]');if(j){e.preventDefault();state.category=j.dataset.categoryJump;state.brand='';state.query='';rendered.catalog=false;showView('catalog',{push:true});return}const suggestion=e.target.closest?.('[data-search-product]');if(suggestion){e.preventDefault();selectSearchProduct(suggestion.dataset.searchProduct);return}const brandChip=e.target.closest?.('[data-brand-chip]');if(brandChip){e.preventDefault();state.brand=brandChip.dataset.brandChip||'';state.category='all';state.query='';rendered.catalog=false;showView('catalog');return}if(e.target.closest?.('#allBrandsBtn,#filterBtn')){e.preventDefault();openFilterSheet();return}const fav=e.target.closest?.('[data-favorite]');if(fav){e.preventDefault();e.stopPropagation();const id=String(fav.dataset.favorite);state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);persistFav();if(state.view==='favorites')renderFavorites();else $$(`[data-favorite="${CSS.escape(id)}"]`).forEach(x=>x.classList.toggle('active',state.favorites.has(id)));return}const add=e.target.closest?.('[data-add]');if(add){e.preventDefault();e.stopPropagation();const p=state.products.find(x=>String(x.id)===String(add.dataset.add));if(p)addSingle(p,1);return}const minus=e.target.closest?.('[data-minus]');if(minus){e.preventDefault();e.stopPropagation();const p=state.products.find(x=>String(x.id)===String(minus.dataset.minus));if(p)addSingle(p,-1);return}const open=e.target.closest?.('[data-open]');if(open){e.preventDefault();const p=state.products.find(x=>String(x.id)===String(open.dataset.open));if(p)openProduct(p);return}const cat=e.target.closest?.('[data-category]');if(cat){e.preventDefault();state.category=cat.dataset.category;state.query='';syncCatalogUI();refreshCatalogResults();return}if(e.target.closest?.('#clearBrand')){e.preventDefault();applyBrandFilter('');return}if(e.target.closest?.('#clearSearch')){e.preventDefault();state.query='';syncCatalogUI();updateSearchSuggestions('');refreshCatalogResults();$('#catalogSearch')?.focus({preventScroll:true});return}if(e.target.closest?.('#resetCatalog')){e.preventDefault();state.category='all';state.brand='';state.query='';syncCatalogUI();refreshCatalogResults();return}const cn=e.target.closest?.('[data-cart-note]');if(cn){openCartNoteEditor(cn.dataset.cartNote);return}const cm=e.target.closest?.('[data-cart-minus]');if(cm){changeCartByKey(cm.dataset.cartMinus,-1);return}const cp=e.target.closest?.('[data-cart-plus]');if(cp){changeCartByKey(cp.dataset.cartPlus,1);return}if(e.target.closest?.('#clearCart')){confirmClearCart();return}if(e.target.closest?.('#checkoutStart')){const stockIssue=cartStockIssue();if(stockIssue)return toast(`Stock insuficiente para ${stockIssue.product.name}`,'error');state.checkoutStep=1;renderCart();window.scrollTo(0,0);return}if(e.target.closest?.('#checkoutBack')){state.checkoutStep=0;renderCart();return}const del=e.target.closest?.('[data-delivery]');if(del){state.delivery=del.dataset.delivery;renderCart();return}const pay=e.target.closest?.('[data-payment]');if(pay){state.paymentMethod=pay.dataset.payment;renderCart();return}if(e.target.closest?.('#reviewBack')){state.checkoutStep=1;renderCart();return}if(e.target.closest?.('#reviewOrder')){const c=collectCustomer();if(!c.business||phoneDigits(c.phone).length<11)return toast('Completa negocio y WhatsApp','error');write(LS.customer,c);state.checkoutStep=2;renderCart();window.scrollTo(0,0);return}if(e.target.closest?.('#submitOrder')){submitOrder();return}if(e.target.closest?.('#refreshOrders')){refreshOrders();return}if(e.target.closest?.('#locationBtn')){if(!navigator.geolocation)return toast('Ubicación no disponible','error');const btn=$('#locationBtn');btn.disabled=true;btn.querySelector('span').textContent='Obteniendo ubicación…';navigator.geolocation.getCurrentPosition(pos=>{state.location={lat:Number(pos.coords.latitude.toFixed(6)),lng:Number(pos.coords.longitude.toFixed(6)),label:'Ubicación compartida por el cliente'};btn.disabled=false;renderCart();toast('Ubicación guardada')},()=>{btn.disabled=false;btn.querySelector('span').textContent='Agregar ubicación actual';toast('No pudimos obtener la ubicación','error')},{enableHighAccuracy:true,timeout:10000,maximumAge:60000});return}if(!e.target.closest?.('.v102-search-wrap'))updateSearchSuggestions('')},true);
document.addEventListener('input',e=>{if(e.target?.id!=='catalogSearch')return;state.query=e.target.value;syncCatalogUI();updateSearchSuggestions(e.target.value);clearTimeout(searchTimer);searchTimer=setTimeout(refreshCatalogResults,90)},true);
document.addEventListener('keydown',e=>{if(e.target?.id==='catalogSearch'&&e.key==='Enter'){const first=$('#searchSuggestions [data-search-product]');if(first){e.preventDefault();selectSearchProduct(first.dataset.searchProduct)}}},true);
$('#shareBtn').onclick=async()=>{const data={title:state.account?.name||'Catálogo',text:'Mira este catálogo',url:location.origin+location.pathname};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(data.url);toast('Enlace copiado')}}catch{}};history.replaceState({v10View:'home'},'',location.pathname);window.addEventListener('popstate',e=>{if(state.sheetOpen){closeSheet();return}showView(e.state?.v10View||'home',{push:false})})}
function hydrate(payload){state.account=payload.account||state.account;state.categories=Array.isArray(payload.categories)?payload.categories:state.categories;state.products=Array.isArray(payload.products)?payload.products:state.products;state.presentations=Array.isArray(payload.presentations)?payload.presentations:state.presentations;reconcileCart();state.popularIds=Array.isArray(payload.popular_product_ids)?payload.popular_product_ids:state.popularIds;if(state.account?.payment_methods?.length&&!state.account.payment_methods.includes(state.paymentMethod))state.paymentMethod=state.account.payment_methods[0];applyAccountBrand();Object.keys(rendered).forEach(k=>rendered[k]=false)}
function renderActive(){renderHome();if(state.view==='catalog')renderCatalog();if(state.view==='favorites')renderFavorites();if(state.view==='orders')renderOrders();if(state.view==='cart')renderCart();updateNavigation();const idle=window.requestIdleCallback||((fn)=>setTimeout(fn,250));idle(()=>{if(!rendered.catalog&&state.view!=='catalog')renderCatalog()},{timeout:1200})}
async function load(){shell();const cached=read(LS.cache,null);if(cached?.account){hydrate(cached);renderActive()}else{$('#homeView').innerHTML='<div class="v10-shell"><div class="v10-loading"><i></i><b>Cargando catálogo…</b></div></div>'}try{const payload=await api('catalog_bootstrap',{slug},{timeout:14000});hydrate(payload);write(LS.cache,{...payload,cached_at:Date.now()});renderActive()}catch{if(!cached){$('#homeView').innerHTML='<div class="v10-shell"><div class="v10-empty big"><b>No pudimos cargar el catálogo</b><span>Revisa tu conexión e inténtalo otra vez.</span><button id="retry">Reintentar</button></div></div>';$('#retry')?.addEventListener('click',()=>location.reload())}}}
if('serviceWorker' in navigator)navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).catch(()=>{});
load();
